  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Trovafloxacin, which shares a primary amine, difluorophenyl, and fused heterocyclic framework with the query, had absolute oral bioavailability of 87.6% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Doravirine, containing a tetrahydropyran/difluorophenyl/fused heterocycle motif similar to the query, had an estimated F of 74.6%, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Genaconazole, with a difluorophenyl and sulfonyl/azole motif, showed 100% absolute oral bioavailability in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "LY3000328, a tetrahydropyran-containing amine with a fluorophenyl group, had oral bioavailability of at least 48.4–66.5% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Lumateperone, a lipophilic fused polycyclic tertiary amine with a fluorophenyl substituent, had absolute oral bioavailability of only 4.4% in humans, providing the main contradictory low-F evidence; its transfer to the query is limited by low structural similarity.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Most retrieved experimental analogues, including those sharing difluorophenyl, tetrahydropyran, sulfonyl/azole, and amine motifs, show high human oral bioavailability (48–100%), while only one distant analogue (lumateperone) shows low F (4.4%). On balance, high F >=20% is better supported, though with low confidence due to weak structural similarity.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "All retrieved analogues have low Morgan similarity (<0.22), limiting structural transferability.",
    "No permeability, solubility, or metabolic stability data are available for the query.",
    "The single low-F analogue (lumateperone) indicates possible first-pass liability, but its relevance to the query is uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

